def check(k):
    add = [0]*(m+2)
    cur = cnt = 0
    for i in range(m):
        cur += add[i]
        if cur < req[i]:
            need = req[i] - cur
            cnt += need
            if cnt > k:
                return False
            cur += need
            add[i+1] -= need
    return True

